templates.template:
/* =============================================================================
   Sudsy — a XenForo 2.3 port of the ProBoards "Sudsy" skin.
   Mint page with the bubbly Sudsy logo, a teal top bar with italic serif links, a quote in
   the header, glossy mint category bars and pale mint rows with serif board titles.
   The logo is embedded below, so the style needs no uploads.
   ============================================================================= */

// The quote shown on the right of the header. Change it, or set it to "" to hide it.
@sudsy-quote: "\201CThe art of art, the glory of expression and the sunshine of the light of letters, is simplicity.\201D";
@sudsy-quote-by: "Walt Whitman";

@sd-serif: Georgia, 'Times New Roman', serif;
@sd-teal: #63bea1;
@sd-link: #3f8a6c;
@sd-bar: linear-gradient(180deg, #8fefd5 0, #6dd3b9 1px, #66ccb1 50%, #5fc4a9 100%);

html
{
	background: linear-gradient(180deg, #7dccaf 0, #7dccaf 300px, #9dd8b7 520px) no-repeat #9dd8b7;
}

body,
.p-pageWrapper
{
	background: transparent;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 1520px;
}

.p-header,
.p-sectionLinks,
.p-body,
.p-footer
{
	background: transparent;
	border: none;
}

// ---- Teal bar across the top with the menu on the right -----------------------------------
// (moved above the logo, as in the original)

.p-staffBar
{
	order: -2;
}

.p-navSticky
{
	order: -1;
}

.p-nav
{
	background: @sd-teal;
	border-bottom: 1px solid #a8ddbf;
	color: #fff;
}

.p-nav-list
{
	justify-content: flex-end;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #fff;
		font-family: @sd-serif;
		font-size: 15px;
		font-style: italic;

		&:hover
		{
			color: #e8fff6;
			text-decoration: underline;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(255, 255, 255, .15);
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #fff;
	font-family: @sd-serif;
	font-style: italic;

	&:hover
	{
		background: rgba(255, 255, 255, .15);
		color: #fff;
		text-decoration: none;
	}
}

// ---- Header: the Sudsy logo, with the quote on the right ----------------------------------

.p-header-content
{
	padding: 22px 0 30px;
	align-items: center;

	&::after
	{
		content: @sudsy-quote "\A" @sudsy-quote-by;
		white-space: pre-line;
		margin-left: auto;
		max-width: 60%;
		color: #fff;
		font-family: @sd-serif;
		font-size: 22px;
		font-style: italic;
		line-height: 1.3;
		text-align: right;
	}
}

.p-header-logo
{
	img
	{
		display: none;
	}

	a
	{
		display: block;
		width: 262px;
		height: 110px;
		background: url("data:image/png;base64,") center / contain no-repeat;
	}
}

@media (max-width: @xf-responsiveMedium)
{
	.p-header-content::after
	{
		display: none;
	}
}

.p-sectionLinks-inner
{
	a
	{
		color: #2f6f58;
	}
}

// ---- Body ------------------------------------------------------------------------------

.p-body-inner
{
	color: #000;
}

.p-breadcrumbs
{
	font-size: 11px;

	a
	{
		color: #2f6f58;
	}
}

.p-title-value
{
	color: #fff;
	font-family: @sd-serif;
	font-style: italic;
	text-shadow: 0 1px 2px rgba(0, 0, 0, .15);
}

// ---- Blocks: glossy mint bars, pale mint rows ------------------------------------------------

.block-container
{
	background: #f0fdfc;
	border: 1px solid #5aad97;
	border-radius: 0;
}

.block-header,
.block-minorHeader,
.block-filterBar,
.menu-header,
.overlay-title,
.dataList-row--header .dataList-cell
{
	background: @sd-bar;
	border-bottom: 1px solid #5aad97;
	color: #fff;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: #e8fff6;
		font-family: @sd-serif;
		font-style: italic;
	}
}

.block-tabHeader,
.menu-tabHeader
{
	background: @sd-bar;
	border-bottom: 1px solid #5aad97;

	.tabs-tab
	{
		color: #e8fff6;

		&:hover,
		&.is-active
		{
			color: #fff;
			border-color: #fff;
		}
	}
}

.block-footer
{
	background: #e2f5ef;
	border-top-color: #bdcfce;
}

.node + .node,
.structItem
{
	border-top-color: #bdcfce;
}

.node-body,
.structItem
{
	background: #f0fdfc;
}

.node-title a,
.structItem-title a
{
	color: @sd-link;
	font-family: @sd-serif;
	font-size: 15px;
	font-weight: 400;

	&:hover
	{
		color: #2f6f58;
	}
}

.node-description
{
	color: #000;
}

.node-stats dt,
.pairs > dt
{
	font-style: italic;
}

.node-icon i
{
	color: #a8c64a;
}

.node--unread .node-icon i
{
	color: #6f9a2a;
}

.message,
.message-inner
{
	background: #f0fdfc;
	border-color: #bdcfce;
}

.message-cell--user
{
	background: #e2f5ef;
	border-right-color: #bdcfce;
}

.message-name a
{
	font-family: @sd-serif;
}

.button.button--primary,
a.button.button--primary
{
	background: @sd-bar;
	border: 1px solid #5aad97;
	color: #fff;

	&:hover
	{
		background: linear-gradient(180deg, #a2f5df 0, #78dac0 1px, #6fd2b7 50%, #66cbb0 100%);
		color: #fff;
	}
}

// ---- Footer ------------------------------------------------------------------------------

.p-footer
{
	color: #2f5f4e;

	a
	{
		color: #2f6f58;
	}
}
